#!/usr/bin/env python3
"""Write results/RESULTS.md from the JSON files the validation scripts produced. No number is typed by hand."""
import collections
import json
import os

from common import RESULTS, prf, prf_text


def load(name):
    p = os.path.join(RESULTS, name)
    return json.load(open(p)) if os.path.isfile(p) else None


def main():
    L = ["# What the survival checker caught, against ground truth", "",
         "Generated by `validation/make_results.py` from the JSON files in this folder. Labels: **MEASURED** = produced here "
         "by running the tool named; **SIMULATED** = output of a fault model (nothing was measured on hardware); **RECORDED** = "
         "copied from a file of the repository or of a sibling module, not re-run; **untested** = written, no ground truth or "
         "not run.", ""]
    head = ["| data set | cases | ground truth | flagged | precision | recall |", "|---|---|---|---|---|---|"]
    table = []
    e2 = load("e2_matrix.json")
    if e2:
        L += ["## 1. Synthesis: the 96-configuration grid per design, re-synthesised here", "",
              "The repository's synthesis-variance study (`research/c2/e2_variance`) lists 864 configurations = 3 Yosys builds x "
              "3 designs x 96 flows, and stores their results but not their netlists. This run rebuilt the 96 flows of V1 and V2 "
              "with each Yosys build available here (script text from the study's own generator), then ran the checker and the "
              "bounded fault search on every netlist. MEASURED."]
        rows = e2["rows"]
        builds = collections.OrderedDict()
        for r in rows:
            builds.setdefault((r["build"], r["yosys"]), []).append(r)
        for (b, ver), rs in builds.items():
            L += ["", f"### Build `{b}` ({ver})", ""]
            for d in sorted({r["design"] for r in rs}):
                ds = [r for r in rs if r["design"] == d and "copies" in r]
                rec = [r for r in ds if r.get("rec_min") is not None]
                L.append(f"**{d.upper()}**: {len(ds)} of {len([r for r in rs if r['design'] == d])} netlists checked.")
                if rec:
                    L.append(f"Same flow as the recorded `{b}` rows: gate count equal to the recorded one in "
                             f"{sum(1 for r in rec if r['gates'] == r['rec_gates'])} of {len(rec)}, minimum flips measured here equal "
                             f"to the recorded minimum in {sum(1 for r in rec if r['min_here'] == r['rec_min'])} of {len(rec)} "
                             f"(byte-identical netlist: {sum(1 for r in rec if r.get('same_netlist_as_recorded'))}; names differ between Yosys builds).")
                solved = [r for r in ds if r.get("min_here") is not None]
                L += ["", "| copies verdict | encoding verdict | min 1 | min 2 | min 3 | no fault search (cells the engines do not model) |", "|---|---|---|---|---|---|"]
                cnt = collections.Counter((r["copies"], r.get("encoding"), r.get("min_here")) for r in ds)
                for cv, ev in sorted({(k[0], k[1]) for k in cnt}):
                    L.append(f"| {cv} | {ev} | {cnt[(cv, ev, 1)]} | {cnt[(cv, ev, 2)]} | {cnt[(cv, ev, 3)]} | {cnt[(cv, ev, None)]} |")
                L.append("")
                if d == "v2":
                    flag = lambda r: r["copies"] != "SURVIVED" or r.get("encoding") != "SURVIVED"   # noqa: E731
                    best = max(r["min_here"] for r in solved)
                    for name, truth in (("minimum flips = 1 (the redundancy gives nothing)", lambda r: r["min_here"] == 1),
                                        (f"minimum flips below {best} (the minimum of the RTL as written)", lambda r: r["min_here"] < best)):
                        tp = sum(1 for r in solved if flag(r) and truth(r))
                        fp = sum(1 for r in solved if flag(r) and not truth(r))
                        fn = sum(1 for r in solved if not flag(r) and truth(r))
                        p = prf(tp, fp, fn)
                        L.append(f"- Truth \"{name}\": {prf_text(p)} over {len(solved)} netlists with a fault search.")
                        table.append(f"| V2 synthesis grid, build {b} | {len(solved)} | {name} (MEASURED here; = RECORDED where recorded) | {tp + fp} | "
                                     f"{'n/a' if p['precision'] is None else '%.2f (%d/%d)' % (p['precision'], tp, tp + fp)} | "
                                     f"{'n/a' if p['recall'] is None else '%.2f (%d/%d)' % (p['recall'], tp, tp + fn)} |")
                    rm = [r for r in ds if r.get("rec_match_nets") is not None]
                    if rm:
                        dis = [r for r in rm if (r["copies"] != "SURVIVED") != (r["rec_match_nets"] < 3 or r["rec_shared"] > 0)]
                        L.append(f"- Against the study's own structural column (RECORDED `distinct_match_nets` < 3 or shared gates > 0): "
                                 f"same answer in {len(rm) - len(dis)} of {len(rm)}. The {len(dis)} differences are "
                                 + "; ".join(sorted({f"`{r['flow']}/{r['order']}/{r['abc']}/{r['merge']}` (recorded: {r['rec_match_nets']} match nets, {r['rec_shared']} shared; checker: {r['independent']} independent; minimum flips {r['rec_min']})" for r in dis}))
                                 + ".")
                    unflag = collections.Counter(r["min_here"] for r in solved if not flag(r))
                    L.append(f"- Not flagged: {dict(sorted(unflag.items()))} (minimum flips: count). The not-flagged netlists below the "
                             "as-written minimum have all copies separate and the encoding intact; the fault search still finds a "
                             "cheaper attack through the next-state logic as this Yosys build maps it. The checker reports these "
                             "as a margin drop (exit 1) without a structural cause.")
                    unsup = [r for r in ds if r.get("min_here") is None]
                    L.append(f"- {len(unsup)} netlists use cells the fault engines do not model (the study's ENGINE_UNSUPPORTED rows); "
                             f"the checker still gives a structural verdict for them: {dict(collections.Counter(r['copies'] for r in unsup))}. untested against a minimum.")
                else:
                    L.append(f"- {d.upper()} is a control: in its RTL one net combines the two copies, so its minimum is 1 in "
                             f"{sum(1 for r in solved if r['min_here'] == 1)} of {len(solved)} netlists and never above "
                             f"{max(r['min_here'] for r in solved)}; a merge cannot lower it. The checker reports the merge of its two "
                             f"copies in {sum(1 for r in ds if r['copies'] != 'SURVIVED')} of {len(ds)} netlists, and every one of those "
                             f"with a fault search has minimum 1 ({sum(1 for r in solved if r['copies'] != 'SURVIVED' and r['min_here'] == 1)} "
                             f"of {sum(1 for r in solved if r['copies'] != 'SURVIVED')}). No precision/recall is given for a control.")
                L.append("")
        L += ["Not covered: the study's other two builds (conda Yosys 0.38, 176 of its 264 solved V2 rows) "
              + ("were not available here; " if not any("0.38" in v for _, v in builds) else "") +
              "their netlists are not stored, so those rows are **untested** by the checker.", ""]
    st = load("stored_netlists.json")
    if st:
        errs = [r for r in st["rows"] if "error" in r]
        L += ["## 2. Synthesis: every V1/V2-family netlist stored in the repository", "",
              f"The {len(st['rows'])} distinct netlists `ext/surface` validates on; {len(errs)} skipped"
              + (" (" + "; ".join(f"`{r['netlist']}`: {r['error']}" for r in errs) + ")" if errs else "") +
              ". Reference: each design's RTL elaborated as written with Yosys. Minimum flips: MEASURED by "
              "`ext/surface` (`results/lint_validation.json`).", "",
              "| netlist | top | copies | encoding | min flips | min as written |", "|---|---|---|---|---|---|"]
        for r in st["rows"]:
            L.append(f"| `{r['netlist']}` | {r['top']} | {r.get('copies', r.get('error', '-'))} | {r.get('encoding', '-')} | {r.get('measured_min')} | {r.get('reference_min', '-')} |")
        L.append("")
        for name, s in st["summary"].items():
            L.append(f"- {name}: {s['netlists']} netlists, {s['flagged']} flagged; truth \"minimum below the as-written minimum\": {s['text']}."
                     + (" Misses: " + "; ".join(f"`{m['netlist']}` ({m['min']} vs {m['as_written']})" for m in s["misses"]) + "." if s["misses"] else ""))
            if name.startswith("v2"):
                table.append(f"| Stored V2-family netlists | {s['netlists']} | minimum flips below the as-written minimum (MEASURED by ext/surface) | {s['flagged']} | "
                             f"{s['precision']:.2f} ({s['tp']}/{s['tp'] + s['fp']}) | {s['recall']:.2f} ({s['tp']}/{s['tp'] + s['fn']}) |")
        L += ["", "Reading: only two stored V2-family netlists are merged, and both are flagged. The misses are not merges: the copies "
              "and the encoding are intact in all of them (apt-0.33 mappings of the next-state logic, and the `v2c04`/`v2c4d` "
              "control designs, whose unoptimised netlist needs 3 flips while their mapped netlists need 1 or 2). The structural verdict cannot see them; the margin "
              "comparison of the same run does (it is the ground truth here, so it is not counted as a detection). The one "
              "flagged V1 netlist is a real merge of V1's two copies that cannot lower V1's minimum of 1.", ""]
    pl = load("placement.json")
    if pl:
        s = pl["summary"]["v2_layouts"]
        L += ["## 3. Placement: six placed layouts against the shot search", "",
              "Geometry MEASURED from the DEF; truth SIMULATED by `ext/shots` (rule centre, free aim, bit flip, 6 cycles): at "
              "each sampled radius, fewer shots than at radius 0 means the placement weakened the redundancy.", "",
              "| layout | copies | radius reaching two copies (um) | radius reaching all copies (um) | shots at radius 0 |", "|---|---|---|---|---|"]
        for k, v in pl["summary"]["per_design"].items():
            L.append(f"| {k} ({v['note']}) | {v['copies']} | {v['r_pair_um']} | {v['r_all_um']} | {v['shots_at_r0']} |")
        fp = [r for r in pl["rows"] if r["design"] != "v1" and r["verdict"] != "SURVIVED" and r["truth"] == "SURVIVED"]
        L += ["", f"- Five V2 layouts, {s['points']} (layout, radius) points: {s['text']}; same class (SURVIVED / WEAKENED / REMOVED) "
              f"as the shot search in {s['exact_class']} of {s['points']}.",
              f"- The {len(fp)} false alarms are radii where one spot already reaches two copies but the shot search still needs all its shots: "
              + ", ".join(f"{d} {min(r['radius_um'] for r in fp if r['design'] == d)}-{max(r['radius_um'] for r in fp if r['design'] == d)} um" for d in sorted({r['design'] for r in fp})) + ".",
              f"- V1 (control): needs 1 shot at every radius whatever the placement; the checker reports its two copies within one "
              f"spot at {pl['summary']['v1_control']['flagged']} of {pl['summary']['v1_control']['points']} radii. Not counted.", ""]
        table.append(f"| Placed V2 layouts x radii | {s['points']} | fewer shots than at radius 0 (SIMULATED by ext/shots) | {s['tp'] + s['fp']} | "
                     f"{s['precision']:.2f} ({s['tp']}/{s['tp'] + s['fp']}) | {s['recall']:.2f} ({s['tp']}/{s['tp'] + s['fn']}) |")
    fw = load("firmware.json")
    if fw:
        s = fw["summary"]
        L += ["## 4. Firmware: 108 builds of the boot ROM", "",
              f"{s['builds']} builds (9 variants x 4 optimisation levels x 3 C styles); {s['builds_with_repeated_checks']} of them contain "
              f"repeated checks in the source ({s['repeated_checks']} repeated checks in all). Truth MEASURED by `ext/firmware` on its "
              "simulator: how many of the repeats are executed in a good boot.", "",
              f"- {s['text']}. Flagged: " + "; ".join(f"`{f['build']}` {f['check']} ({f['intended']} written, {f['executed_in_truth']:g} executed; "
                                                      f"minimum instruction faults {f['min_faults']}, SIMULATED)" for f in s["flagged"]) + ".",
              "- This is the -O2 merge: three MAC compares in ordinary C become one. The volatile and barrier builds of the same "
              "source are not flagged, in agreement with the truth.",
              "- One positive case only, and the rule that counts inlined copies was adjusted while looking at these builds "
              "(two false alarms on `rom_compl` were removed that way). The 1/1 is therefore a fit, not an independent test.",
              f"- Flow counters: {s['flow_counters']['found']} found, verdicts {s['flow_counters']['verdicts']}; no ground truth is recorded for them: **untested**.", ""]
        table.append(f"| Firmware repeated checks | {s['repeated_checks']} | fewer repeats executed than written (MEASURED by ext/firmware, simulator) | {s['tp'] + s['fp']} | "
                     f"{s['precision']:.2f} ({s['tp']}/{s['tp'] + s['fp']}) | {s['recall']:.2f} ({s['tp']}/{s['tp'] + s['fn']}) |")
    re_ = load("real_designs.json")
    if re_:
        L += ["## 5. Real netlists: OpenTitan AES cipher-control FSM (lowRISC/synfi, Yosys + Nangate45)", "",
              "| stage | countermeasure | verdict | evidence | recorded minimum flips (state flops only / any cell) |", "|---|---|---|---|---|"]
        for r in re_["rows"]:
            rec = r.get("recorded") or {}
            L.append(f"| {r['stage']} | {r['countermeasure']} | {r['verdict']} | {r['evidence'][0][:170]} | "
                     f"{rec.get('min_flips_state_flops_only')} / {rec.get('min_flips_any_cell')} (RECORDED, {rec.get('source')}) |")
        L += ["", re_["reading"], "",
              "No precision or recall here: there is no netlist of this FSM with a broken encoding to test against, so the "
              "\"REMOVED\" side is **untested** on real designs. The three-rail sample visits two codes only (random inputs "
              "drive the FSM into its error state), so its distance figure covers those two codes.", ""]
        table.append("| OpenTitan AES FSM netlists | 2 | none available (encoding intact per the recorded SAT analysis) | 0 | n/a | n/a |")
    L[4:4] = ["## Summary", ""] + head + table + [
        "", "\"Flagged\" = the checker's structural verdict is WEAKENED or REMOVED for at least one countermeasure. The margin "
        "comparison between stages is not counted as a detection anywhere in this table, because the minimum number of faults "
        "is the ground truth.", ""]
    with open(os.path.join(RESULTS, "RESULTS.md"), "w") as f:
        f.write("\n".join(L) + "\n")
    print("\n".join(head + table))


if __name__ == "__main__":
    main()
